    profileDesc: 'کنترل کنید کاربران چه چیزی را می‌توانند یا نمی‌توانند ببینند در حالی که قادرید داده‌های دنبال‌کنندگان خود را در هر زمان صادر کنید.',
    topUpTitle: 'شارژ توکن‌ها در ۲ کلیک',
    topUpShotAlt: 'خرید توکن‌های DeHub مستقیماً از داخل برنامه.',
    topUpDesc: 'ما ارز درون برنامه‌ای خودمان را داریم، شبیه به ویباکس‌هایی که در فورتنایت یا تیک‌تاک دریافت می‌کنید، ارز ما توکن‌های DeHub نام دارند. شما این ارزها را به عنوان سکه‌های طلا در سراسر برنامه خواهید دید. آنها برای خدمات پریمیوم مانند انعام، اشتراک و موارد دیگر استفاده می‌شوند. مرور رایگان است، و همچنین ارسال پست در داخل سهمیه روزانه هر حساب نیز رایگان است - اگر با شبکه‌های اجتماعی، ایمیل یا پیامک ثبت نام کنید، ما تمام هزینه‌های گس را برای شما حمایت می‌کنیم. کاربران کیف پول، گس استاندارد ETH یا BNB را پرداخت می‌کنند. توکن‌ها را با ۲ کلیک در زیر شارژ کنید.',
