    feeTierDesc: 'ساختار کارمزد انقلابی ما به دارندگان توکن DeHub، کارمزد پلتفرم را به طور قابل توجهی کاهش می‌دهد. با شروع از کارمزد استاندارد ۱۰٪، هر سطح نشان که از طریق افزایش موجودی توکن به دست می‌آید، کارمزدها را ۰.۶۹٪ کاهش می‌دهد و در نهایت برای دارندگان نشان Megalodon به تنها ۱٪ می‌رسد - ۹۹٪ کاهش کارمزد برای وفادارترین اعضای جامعه ما.',
