    altUpload: 'سازنده پست، با گزینه‌های عنوان، دسته‌بندی، انجمن و فقط مشترکین',
    altProfile: 'صفحه پروفایل DeHub',
    altExplore: 'صفحه اکسپلور، جستجوی افراد، پست‌ها و رسانه‌ها در DeHub',
