    spNameCommentAnchor: 'لنگر نظر',
    spDescCommentAnchor: 'بالای تاپیک نظرات دیگران را نگه دارید. نه پین ​​رایگانی که نویسنده از قبل در پست خودش دارد - این پین مال شماست، در تاپیک آنها، و منقضی می‌شود.',
    spNameTrendJacker: 'ترند جکر',
    spDescTrendJacker: 'یکی از دسته‌بندی‌های خود را در فهرست ترندها قرار دهید، جایی که کل پلتفرم از قبل به دنبال آن است.',
    spNameTimelineBomber: 'بمب افکن تایم لاین',
    spDescTimelineBomber: 'دنبال‌کنندگان شما پست شما را قبل از پست‌های دیگران می‌بینند، بنابراین برای افرادی که تصمیم گرفته‌اند از شما بشنوند، یک شاه کبرا در قرعه‌کشی در مقابل یک مگالودون برنده می‌شود.',
