    spNameFlakJacket: 'ژاکت ضدگلوله',
    spDescFlakJacket: 'پست شما نمی‌تواند در حین انتشار با رأی منفی پنهان شود - مصونیت از انبوه نظرات، نه از اختلاف نظر.',
    spNamePrecisionStrike: 'ضربه دقیق',
    spDescPrecisionStrike: 'به افرادی که حسابی را که شما نامگذاری کرده‌اید دنبال می‌کنند، دسترسی پیدا کنید، چه آنها شما را دنبال کنند و چه نکنند.',
    spNameHarpoon: 'هارپون',
    spDescHarpoon: 'به هر دارنده نشان در سطوح نشان که انتخاب می‌کنید، در مورد یک پست اطلاع دهید. همچنین از محل سهمیه سیگنال پرداخت می‌شود.',
    spNameTeamUp: 'تیم سازی کنید',
    spNameFrontRow: 'ردیف جلو',
    spDescFrontRow: 'صحنه‌ی زنده‌ی شما در حین اجرا، روی هر سطحی که صحنه‌ها را فهرست می‌کند، بالای نرده‌ی صحنه قرار می‌گیرد.',
    spNameDeepCurrent: 'جریان عمیق',
    spDescDeepCurrent: 'یکی از امتیازات خود را به پست شخص دیگری بدهید. بالاترین رتبه، رتبه‌ای است که دسترسی شما را به افراد دیگر اختصاص می‌دهد.',
    spLadderTitle: 'هر نشان چه چیزی اعطا می‌کند؟',
    spLadderDesc: 'افزایش‌ها در هر دو هفته و مدت زمان اجرای هر کدام. هیچ یک از ستون‌ها با بالا رفتن شما کاهش نمی‌یابند و مجموع آنها همیشه افزایش می‌یابد.',
    spColUnlocks: 'قفل‌ها را باز می‌کند',
    spMinShort: 'دقیقه',
    spNoAllowance: 'بدون کمک هزینه',
    spQuantityOnly: 'دسترسی بیشتر، بدون قدرت جدید',
    spRotationTitle: 'نحوه اشتراک‌گذاری اسلات',
    spRotationDesc: 'این جایگاه به جای پین کردن، می‌چرخد. وقتی چندین بوست به طور همزمان اجرا می‌شوند، به هر بیننده یک بوست داده می‌شود که بر اساس سطح نشان بوست کننده وزن‌دهی می‌شود - سطح بالاتر بیشتر نمایش داده می‌شود و همه همچنان پنجره‌ای را که برای آن هزینه کرده‌اند، دریافت می‌کنند. چیزی که یک بوست می‌خرد، سهمی از صدا برای مدت زمان مشخصی است، نه مالکیت انحصاری بالای فید.',
    spCycleTitle: 'یک ساعت برای همه',
    spCycleDesc: 'این چرخه در کل پلتفرم چهارده روز است، بنابراین سهمیه همه در یک لحظه پر می‌شود. هیچ چیز به زمان دیگری منتقل نمی‌شود. رزرو را قبل از شروع لغو کنید و دقایق به چرخه‌ای که از آن به آنها پرداخت کرده‌اید، برمی‌گردند.',
    spSafetyTitle: 'کاری که یک بوست نمی‌تواند انجام دهد',
    spSafetyDesc: 'هر قرعه‌کشی دوباره با توجه به پست فعلی بررسی می‌شود، بنابراین پستی که از آن زمان حذف، مسدود یا به عنوان پست ویژه بزرگسالان علامت‌گذاری شده است، هرگز به فید یک غریبه نمی‌رسد. پست‌های ویژه بزرگسالان نیز در هنگام رزرو رد می‌شوند و هرگز به کسی که شما را مسدود کرده یا شخصی که شما او را بوست کرده‌اید، بوست داده نمی‌شود.',
