    featureBoardTitle: 'درخواست‌های ویژه',
    featureBoardDesc: 'DeHub با همکاری جامعه‌ی خود ساخته شده است. ایده‌ها را در صفحه‌ی درخواست ویژگی ارسال کنید، به درخواست‌های دیگران رأی دهید و شاهد انتقال آنها به «ارسال‌شده» باشید - اگر ویژگی‌ای که درخواست کرده‌اید فعال شود، برنامه با یک اعلان شخصی به شما اطلاع می‌دهد.',
    connectTitle: 'هوش مصنوعی متصل (MCP)',
    connectDesc: 'DeHub را از طریق MCP به ChatGPT یا Claude متصل کنید و از هوش مصنوعی مورد علاقه خود برای مرور، ارسال پست و تعامل با پلتفرم از طرف خود استفاده کنید. آن را در dehub.io/connect تنظیم کنید.',
    notificationsTitle: 'اعلان‌ها',
    notificationsDesc: 'هر اتفاقی که برای شما می‌افتد در یک مرکز اعلان‌ها قرار می‌گیرد که به تب‌های جداگانه تقسیم شده است تا پاسخ‌ها، پرداخت‌ها را از بین نبرند. نظرات و پاسخ‌ها، واکنش‌ها به پست‌های شما، دنبال‌کنندگان جدید، نکات و خریدها، یادآوری‌های صحنه و لحظه‌ای که صحنه‌ای که رزرو کرده‌اید پخش می‌شود، فعالیت‌های انجمن و هشداری که هنگام ارسال ویژگی‌ای که در صفحه درخواست‌ها درخواست کرده‌اید، نمایش داده می‌شود - همه در یک مکان، با یک تصویر کوچک از هر آنچه اعلان در مورد آن است تا بتوانید با یک نگاه آنها را از هم تشخیص دهید.',
    notificationsB1: 'آنچه را که به دستتان می‌رسد انتخاب کنید:',
    notificationsB2: 'فشار دادن روی وب و موبایل:',
    notificationsB2Desc: 'هر دو برنامه به خود دستگاه فشار می‌آورند - مرورگر یک بار درخواست اجازه می‌کند، برنامه اندروید هنگام نصب درخواست می‌کند - و همه چیز در هر صورت در مرکز اعلان‌ها قرار می‌گیرد.',
    notificationsB3: 'اطلاعیه‌ها:',
    notificationsB3Desc: 'اعلان‌های سراسری پلتفرم، به جای اینکه در یک صندوق ورودی جداگانه برای بررسی ارسال شوند، از طریق یک مرکز واحد به دست کاربران می‌رسند.',
    notificationsB4: 'از طریق ایمیل:',
    notificationsB4Desc: 'یک آدرس ایمیل را لینک کنید و دسته‌هایی که انتخاب می‌کنید نیز به صندوق ورودی شما می‌رسند، که همان چیزی است که چیزهایی را که ترجیح می‌دهید در حین بسته بودن برنامه از دست ندهید، ثبت می‌کند.',
    notificationsB5: 'از طریق متن:',
    notificationsB5Desc: 'پیامک‌ها یک کانال پولی هستند. یک بار قفل آن را باز کنید، شماره را تأیید کنید، موجودی کمی داشته باشید و انتخاب کنید که آیا هر اعلانی که روشن کرده‌اید برای شما پیامک ارسال کند یا فقط اعلان‌هایی که شامل پول هستند. این سوئیچ هزینه یک پیام و موجودی باقی‌مانده را شامل می‌شود، زیرا دکمه‌ای که بی‌سروصدا شروع به خرج کردن می‌کند، چیزی است که هرگز نباید باشد.',
    themesTitle: 'تم‌ها و ظاهر',
    themesDesc2: 'دو تا از پوسته‌ها یک بازی را پنهان می‌کنند. اگر تم را روی جنگ تنظیم کنید، کلود آو دیوتی از داخل آن قابل دسترسی است؛ اگر آن را روی جنگل تنظیم کنید، مسیر جنگل قابل دسترسی است. هر دو در بازی آرکید هم هستند، اما تم جایی است که به آن تعلق دارند.',
    appsTitle: 'دریافت اپلیکیشن',
    appsDesc: 'DeHub همه جا اجرا می‌شود. اپلیکیشن وب dehub.io محصول کاملی در مرورگر است و مانند یک اپلیکیشن بومی روی صفحه اصلی شما، هم روی دسکتاپ و هم روی گوشی، نصب می‌شود. اپلیکیشن اندروید در گوگل پلی موجود است و آخرین نسخه آن همیشه به صورت APK مستقیم از dehub.io/apk برای هر کسی که ترجیح می‌دهد از فروشگاه صرف نظر کند، در دسترس است. فیدها، استیج‌ها، ارسال پست، پیام‌رسانی، کیف پول و اعلان‌ها همگی در هر دو مورد به یک شکل کار می‌کنند و حساب، نشان و موجودی شما بین آنها تغییر می‌کند.',
    appsB1: 'وب:',
    appsB1Desc: 'dehub.io در هر مرورگر مدرنی، قابل نصب روی صفحه اصلی یا دسکتاپ شما.',
    appsB2: 'اندروید:',
    appsB2Desc: 'در گوگل پلی، یا به عنوان دانلود مستقیم APK از dehub.io/apk برای اندروید ۸ و بالاتر.',
    appsB3: 'یک حساب کاربری در همه جا:',
    appsB3Desc: 'ورود به سیستم، کیف پول، نشان و موجودی یکسان در تمام سطوح، بدون هیچ مرحله انتقال جداگانه‌ای.',
    studioTitle: 'استودیو سازنده و ویرایشگر',
    studioDesc: 'استودیو خالق جایی است که محتوا به جای ارسال، ساخته می‌شود. این استودیو تصاویر، ویدیو، موسیقی، صدا و مدل‌های سه‌بعدی را از طریق یک اعلان تولید می‌کند، در حالی که شما به مرور برنامه ادامه می‌دهید، صف رندر را فعال نگه می‌دارد و نتایج را برای تنظیم، برش و زیرنویس به یک ویرایشگر به سبک Canva تحویل می‌دهد. یک کتابخانه رایگان از فایل‌های آماده در کنار آن قرار دارد، بنابراین می‌توان یک پست را از ابتدا تا انتها بدون ابزار خارجی یا اشتراک در یکی از آنها ساخت.',
    studioDesc2: 'در کنار آن یک ویرایشگر ویدیوی کامل وجود دارد که در مرورگر اجرا می‌شود - یک جدول زمانی چند آهنگه واقعی با برش، لایه‌بندی و خروجی، نه یک اسلایدر برش. فیلم‌هایی که در استودیو تولید کرده‌اید، رسانه‌هایی که آپلود کرده‌اید و هر چیزی از کتابخانه‌ی دارایی‌ها، همگی در یک جدول زمانی قرار می‌گیرند و نسخه نهایی مستقیماً به یک پست، یک فیلم کوتاه یا یک فهرست فروشگاه می‌رود.',
    studioB1: 'تولید کردن:',
    studioB1Desc: 'تصاویر، ویدیو، موسیقی، صدای خارج از تصویر و مدل‌های سه‌بعدی، در تمام مدل‌هایی که استودیو ارائه می‌دهد، قبل از اجرای کار توسط سرور قیمت‌گذاری و قیمت‌گذاری می‌شوند.',
