    thirdPartyItem9: 'مون‌پی (MoonPay) اتریوم (ETH) و یو‌اس‌دی کوین (USDC) را با کارت می‌فروشد، و نیِر اینتِنتس (NEAR Intents)، دِبریج (deBridge) و صرافی‌های غیرمتمرکز، ارزهای دیجیتال شما را تبدیل می‌کنند؛ هر کدام، پرداختی را که مدیریت می‌کنند، می‌بینند.',
    thirdPartyItem10Prefix: 'چند پستی:',
    thirdPartyItem10: 'وقتی حساب‌های اجتماعی دیگر را متصل می‌کنید، پست‌هایی که برای ارسال انتخاب می‌کنید از طریق یک سرویس ارسال به آن پلتفرم‌ها و از طریق امضاکننده‌ای که تأیید می‌کنید به Farcaster ارسال می‌شوند.',
    dataSovereigntyItem5: 'شما انتخاب می‌کنید که آیا سیستم‌های هوش مصنوعی می‌توانند روی کار شما آموزش ببینند یا خیر. این کار مجاز است، مگر اینکه آن را در تنظیمات غیرفعال کنید و انتخاب شما برای خزنده‌های صفحاتی که ما کنترل می‌کنیم منتشر می‌شود.',
    dataSovereigntyItem6: 'شما می‌توانید حساب کاربری خود را از تنظیمات حذف کنید؛ نمایه، آپلودها و رسانه‌های ذخیره شده شما، از جمله نسخه‌های پشتیبان، پاک می‌شوند.',
    whatWeDoCollect: 'آنچه ما جمع آوری می کنیم:',
    doCollectItem2: 'حساب کاربری شما: نام کاربری، جزئیات پروفایل، آواتار، کسانی که دنبال می‌کنید و تنظیماتی که انتخاب می‌کنید. چندین پروفایل می‌توانند روی یک دستگاه قرار بگیرند و هر کدام به یک شکل ذخیره می‌شوند.',
    doCollectItem3: 'آنچه منتشر می‌کنید - پست‌ها، نظرات، آپلودها و ابرداده‌های پیرامون آنها - تا بتواند در اختیار افرادی که آن را برایشان منتشر کرده‌اید، قرار گیرد.',
    doCollectItem4: 'آنچه محصول برای اجرا نیاز دارد: تعداد بازدید و تعامل بر اساس پست‌ها محاسبه می‌شود، و یک شناسه دستگاه که یک جلسه را قابل انتساب نگه می‌دارد تا بتوانید جلسات فعال خود را ببینید و لغو کنید.',
    doCollectItem5: 'سوابق پرداخت هر چیزی که خریداری می‌کنید، چه از طریق Stripe و چه به صورت درون زنجیره‌ای، برای حسابداری و رفع اختلافات نگهداری می‌شود. شماره کارت‌ها توسط Stripe مدیریت می‌شوند و هرگز به دست ما نمی‌رسند.',
    doCollectItem6: 'تشخیص زمانی که چیزی خراب می‌شود، تا بتوان آن را تعمیر کرد.',
